# Credit Risk XAI - Phase 6: LLM-as-Judge Evaluation
# =====================================================
# Uses a DIFFERENT model (qwen/qwen3.8-27b, 27B params) as an independent
# judge to evaluate the 15 classification explanations generated by the
# primary model (openai/gpt-oss-120b, 120B params) in Phase 5.
#
# Deliberately using a different model family to reduce self-preference
# bias — if we used the same model to judge its own output, it would
# likely rate itself more favorably.
#
# Scores: faithfulness (1-10), understandability (1-10), actionability (1-10)
#
# Run: python src/llm_judge.py

import os
import sys
import json
import csv
import re
import time

from dotenv import load_dotenv
from groq import Groq, RateLimitError, APIStatusError, NotFoundError

load_dotenv()

# ---- Configuration ---------------------------------------------------------
# Using a deliberately DIFFERENT model from the generation model
# (openai/gpt-oss-120b) to reduce self-preference bias.
JUDGE_MODEL = "qwen/qwen3.8-27b"
MAX_RETRIES = 3
RETRY_DELAY = 10
API_DELAY   = 3   # seconds between calls
TEMPERATURE = 0.0  # deterministic judging

# ---- Paths ------------------------------------------------------------------
REPORTS     = "reports"
SHAP_LOCAL  = os.path.join(REPORTS, "shap_local")
CF_DIR      = os.path.join(REPORTS, "counterfactuals")
LLM_DIR     = os.path.join(REPORTS, "llm_explanations")
EVAL_DIR    = os.path.join(REPORTS, "evaluation")
PROMPTS_DIR = "prompts"

os.makedirs(EVAL_DIR, exist_ok=True)


def call_judge(prompt):
    """Call the judge model and return the raw response text."""
    api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        raise RuntimeError("GROQ_API_KEY not found in .env")

    client = Groq(api_key=api_key)

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            response = client.chat.completions.create(
                model=JUDGE_MODEL,
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "You are a strict, impartial evaluator of AI-generated "
                            "explanations. Return ONLY valid JSON, no markdown fences, "
                            "no commentary."
                        ),
                    },
                    {"role": "user", "content": prompt},
                ],
                temperature=TEMPERATURE,
                max_tokens=512,
            )
            return response.choices[0].message.content.strip()

        except RateLimitError:
            if attempt < MAX_RETRIES:
                print(f"    [RATE LIMIT] waiting {RETRY_DELAY}s ...")
                time.sleep(RETRY_DELAY)
            else:
                raise

        except NotFoundError as e:
            raise RuntimeError(f"Judge model '{JUDGE_MODEL}' not found: {e}")

        except APIStatusError as e:
            if attempt < MAX_RETRIES:
                print(f"    [API ERROR] {e} - retrying ...")
                time.sleep(RETRY_DELAY)
            else:
                raise


def parse_judge_json(raw_text):
    """
    Parse the judge's JSON response.
    Handles cases where the model wraps it in markdown code fences.
    Returns the parsed dict, or None if parsing fails.
    """
    # Strip markdown code fences if present
    text = raw_text.strip()
    # Remove ```json ... ``` or ``` ... ```
    text = re.sub(r"^```(?:json)?\s*\n?", "", text)
    text = re.sub(r"\n?```\s*$", "", text)
    text = text.strip()

    # Some models include a thinking block — strip it
    # Look for </think> and take everything after it
    if "</think>" in text:
        text = text.split("</think>")[-1].strip()

    # Try to find JSON object in the text
    # Look for the first { and last }
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end != -1 and end > start:
        text = text[start:end + 1]

    try:
        data = json.loads(text)
        # Validate required keys
        required = [
            "faithfulness_score", "faithfulness_reasoning",
            "understandability_score", "understandability_reasoning",
            "actionability_score", "actionability_reasoning",
        ]
        for key in required:
            if key not in data:
                return None
        return data
    except (json.JSONDecodeError, ValueError):
        return None


def build_ground_truth_section(instance_id, case_type, arm):
    """
    Build the ground-truth section of the judge prompt based on the arm.
    """
    sections = []

    if arm in ("shap_only", "combined"):
        shap_path = os.path.join(SHAP_LOCAL, f"{instance_id}_{case_type}.json")
        with open(shap_path) as f:
            shap_records = json.load(f)
        top3 = shap_records[:3]
        lines = ["**Top-3 SHAP features (ground truth):**"]
        for rec in top3:
            lines.append(
                f"  - {rec['feature_name']}: value={rec['feature_value']:.4g}, "
                f"SHAP={rec['shap_value']:+.4f}"
            )
        sections.append("\n".join(lines))

    if arm in ("cf_only", "combined"):
        cf_path = os.path.join(CF_DIR, f"{instance_id}_{case_type}_feasible.json")
        with open(cf_path) as f:
            feasible = json.load(f)
        if feasible:
            best = min(feasible, key=lambda c: c["proximity_score"])
            lines = ["**Counterfactual changes (ground truth):**"]
            for ch in best["changed_features"]:
                lines.append(
                    f"  - {ch['feature_name']}: "
                    f"{ch['original_value']:.4g} -> {ch['cf_value']:.4g} "
                    f"({ch['direction']})"
                )
            sections.append("\n".join(lines))
        else:
            sections.append(
                "**Counterfactual changes:** No feasible counterfactuals "
                "were found for this instance."
            )

    return "\n\n".join(sections)


def format_instance_features(inst):
    """Format an instance's features as a readable string."""
    feats = inst["features"]
    lines = []
    for name, val in feats.items():
        lines.append(f"{name}={val:.4g}")
    return ", ".join(lines)


def run_llm_judge():
    """Evaluate all 15 classification explanations with the LLM judge."""
    print("\n" + "=" * 60)
    print("LLM-AS-JUDGE EVALUATION")
    print("=" * 60)
    print(f"  Judge model: {JUDGE_MODEL}")
    print(f"  Generation model was: openai/gpt-oss-120b")
    print(f"  (Different model to reduce self-preference bias)")

    # Load judge template
    with open(os.path.join(PROMPTS_DIR, "judge_template.txt")) as f:
        template = f.read()

    # Load instances
    with open(os.path.join(REPORTS, "selected_instances.json")) as f:
        all_insts = json.load(f)
    clf_insts = [i for i in all_insts if i["task"] == "classification"]

    arms = ["shap_only", "cf_only", "combined"]
    results = []
    failures = []
    total = len(clf_insts) * len(arms)
    call_num = 0

    for inst in clf_insts:
        iid = inst["instance_id"]
        case = inst["case_type"]

        # Predicted outcome as human-readable text
        pred_class = 1 if inst["predicted_proba"] >= 0.5 else 0
        predicted_outcome = (
            f"HIGH RISK / likely to default (probability: "
            f"{inst['predicted_proba']:.1%})"
            if pred_class == 1
            else f"LOW RISK / unlikely to default (probability: "
                 f"{inst['predicted_proba']:.1%})"
        )

        instance_features = format_instance_features(inst)

        for arm in arms:
            call_num += 1

            # Load the explanation
            llm_path = os.path.join(LLM_DIR, f"{iid}_{case}_{arm}.json")
            with open(llm_path, encoding="utf-8") as f:
                llm_data = json.load(f)
            explanation_text = llm_data["raw_response"]

            # Build ground truth section
            gt_section = build_ground_truth_section(iid, case, arm)

            # Fill the template
            prompt = template.format(
                predicted_outcome=predicted_outcome,
                instance_features=instance_features,
                ground_truth_section=gt_section,
                explanation_text=explanation_text,
            )

            print(f"\n  [{call_num}/{total}] id={iid} case={case} arm={arm}")

            # Call judge with retry for JSON parsing
            parsed = None
            for parse_attempt in range(3):
                try:
                    raw_response = call_judge(prompt)
                    parsed = parse_judge_json(raw_response)
                    if parsed:
                        break
                    else:
                        print(f"    [PARSE FAIL] attempt {parse_attempt+1}/3 "
                              "- retrying ...")
                        time.sleep(API_DELAY)
                except Exception as e:
                    print(f"    [ERROR] {e}")
                    time.sleep(API_DELAY)

            if parsed:
                print(f"    faith={parsed['faithfulness_score']}  "
                      f"understand={parsed['understandability_score']}  "
                      f"action={parsed['actionability_score']}")
                results.append({
                    "instance_id":      iid,
                    "case_type":        case,
                    "arm":              arm,
                    "faithfulness_score":         parsed["faithfulness_score"],
                    "faithfulness_reasoning":     parsed["faithfulness_reasoning"],
                    "understandability_score":    parsed["understandability_score"],
                    "understandability_reasoning": parsed["understandability_reasoning"],
                    "actionability_score":        parsed["actionability_score"],
                    "actionability_reasoning":    parsed["actionability_reasoning"],
                    "judge_model":               JUDGE_MODEL,
                })
            else:
                print(f"    [SKIP] Could not parse judge response after 3 attempts")
                failures.append({
                    "instance_id": iid,
                    "case_type":   case,
                    "arm":         arm,
                    "raw_response": raw_response if 'raw_response' in dir() else "N/A",
                })

            time.sleep(API_DELAY)

    # Save results
    if results:
        csv_path = os.path.join(EVAL_DIR, "llm_judge_scores.csv")
        fieldnames = [
            "instance_id", "case_type", "arm",
            "faithfulness_score", "faithfulness_reasoning",
            "understandability_score", "understandability_reasoning",
            "actionability_score", "actionability_reasoning",
            "judge_model",
        ]
        with open(csv_path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(results)
        print(f"\n  [saved] {csv_path}  ({len(results)} rows)")

    # Save failures
    if failures:
        fail_path = os.path.join(EVAL_DIR, "judge_failures.log")
        with open(fail_path, "w", encoding="utf-8") as f:
            for fail in failures:
                f.write(json.dumps(fail, ensure_ascii=False) + "\n")
        print(f"  [saved] {fail_path}  ({len(failures)} failures)")

    # Print summary
    print("\n  --- Summary by arm ---")
    for arm in arms:
        arm_results = [r for r in results if r["arm"] == arm]
        if arm_results:
            avg_f = sum(r["faithfulness_score"] for r in arm_results) / len(arm_results)
            avg_u = sum(r["understandability_score"] for r in arm_results) / len(arm_results)
            avg_a = sum(r["actionability_score"] for r in arm_results) / len(arm_results)
            print(f"  {arm:10s}: faith={avg_f:.1f}  "
                  f"understand={avg_u:.1f}  action={avg_a:.1f}  "
                  f"(n={len(arm_results)})")


if __name__ == "__main__":
    run_llm_judge()
